mapper.select:
SELECT s.id as staff_id, s.sname as staff_name, s.depart_id, d.dname as depart_name, COALESCE(SUM(CASE WHEN wp.transaction_type = 'EARN' THEN wp.points_value ELSE 0 END), 0) as total_earned, COALESCE(SUM(CASE WHEN wp.transaction_type = 'USE' THEN wp.used_points ELSE 0 END), 0) as total_used, COALESCE(SUM(CASE WHEN wp.transaction_type = 'EARN' THEN wp.points_value ELSE 0 END) - SUM(CASE WHEN wp.transaction_type = 'USE' THEN wp.used_points ELSE 0 END), 0) as current_balance, COUNT(CASE WHEN wp.auto_generated = 1 THEN 1 END) as auto_earned_count, MAX(wp.transaction_time) as last_earn_time FROM hr_employee s LEFT JOIN sys_department d ON s.depart_id = d.id LEFT JOIN hr_welfare_points wp ON s.id = wp.staff_id AND wp.status = 1
AND wp.transaction_time >= #{startDate}
WHERE s.status = '正常'
AND s.depart_id = #{departId}
GROUP BY s.id, s.sname, s.depart_id, d.dname ORDER BY current_balance DESC
LIMIT #{limit}
